package ai.taskforge.security;
import ai.taskforge.repo.UserRepository; import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter; import java.util.*;
@Component public class AuthFilter extends OncePerRequestFilter { private final JwtService jwt; private final UserRepository users; public AuthFilter(JwtService j,UserRepository u){jwt=j;users=u;} protected void doFilterInternal(HttpServletRequest r,HttpServletResponse s,FilterChain c)throws ServletException,java.io.IOException {String h=r.getHeader("Authorization"); if(h!=null&&h.startsWith("Bearer "))try{var u=users.findById(jwt.subject(h.substring(7))).orElseThrow(); var a=new UsernamePasswordAuthenticationToken(u,null,List.of(new SimpleGrantedAuthority("ROLE_"+u.getRole()))); SecurityContextHolder.getContext().setAuthentication(a);}catch(Exception ignored){} c.doFilter(r,s);} }
